mapper.update:
update points_goods
name = #{name}, description = #{description}, image = #{image}, points_required = #{pointsRequired}, stock = #{stock}, total_exchanged = #{totalExchanged}, status = #{status}, sort_order = #{sortOrder},
where id = #{id}

mapper.select:
select * from points_goods
and name like concat('%', #{name}, '%') and status = #{status}
order by sort_order asc, create_time desc

select id, name, stock, points_required, version
from points_goods
where id = #{id}
